for k,v in data['totals'].items():
    if isinstance(v,float) and v != round(v,2): errors.append(f'bad rounding totals.{k}={v}')
lines=[l for l in summary.read_text().splitlines() if l.strip()]
for needed in ['Total 28-day annual margin','Total 56-day annual margin','Absolute margin difference',data['recommendation']['decision']]:
